import json, os, re

inp1 = G['Demo pair 1 input']; out1 = G['Demo pair 1 output']
inp2 = G['Demo pair 2 input']; out2 = G['Demo pair 2 output']

def solve(inp, sweep_both=False, stop_before=True, tie_upper=True):
    H,W=len(inp),len(inp[0])
    # find bars: connected same-non-bg straight runs >1 cell
    from collections import deque
    seen=[[False]*W for _ in range(H)]
    bars=[]
    for i in range(H):
        for j in range(W):
            if inp[i][j]!=5 and not seen[i][j]:
                c=inp[i][j]; q=deque([(i,j)]);seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and inp[x][y]==c:
                            seen[x][y]=True;q.append((x,y))
                # orient
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                horizontal = max(rs)-min(rs)<max(cs)-min(cs)
                bars.append(dict(cells=cells,color=c,horizontal=horizontal))
    return bars

