                comp.append(dict(cells=cells,color=c,single=(len(cells)==1)))
    out=[row[:] for row in inp]
    sc = comp[0]['color']  # seed/bar color (non-bg color)
    # find non-bar cells -> seeds
    seeds=[d for d in comp if d['single']]
    walls=[d for d in comp if not d['single']]
    # seeds -> 4, passive
    for s in seeds:
        r,c=s['cells'][0]; out[r][c]=4
    def ray_fill(start, step, end):
        rr=start[0]+step[0]; cc=start[1]+step[1]
        while 0<=rr<end[0] and 0<=cc<end[1]:
            v=out[rr][cc]
            if v!=bgc: break
            out[rr][cc]=sc; rr+=step[0]; cc+=step[1]
    # each wall fires from EVERY cell perpendicular, toward interior (down for top, up for bottom, left/right for vertical)
    # determine direction per wall by testing which side is "interior": prefer toward grid center-ish
    # heuristic: fire in direction where more bg cells exist along perpendicular line within grid
    dirs={(0,0):None}
    for w in walls:
        rs=[p[0] for p in w['cells']]; cs=[p[1] for p in w['cells']]
