                cands[(dc,col)]=cnt_d
        else:
            for dr in (-1,1):
                row=min(rs)+(1 if dr==1 else 0)
                cnt_d=int(sum(1 for cc in range(min(cs)+1,W) if inp[row][cc]==bgc))
                cands[(dr,row)]=cnt_d
        c=sorted(cands.items(), key=lambda t:-t[1])[0][0]
        for cell in w['cells']:
            rr,cc=cell
            dr,dc=c
            while 0<=rr+dr<H and 0<=cc+dc<W and inp[rr+dr][cc+dc]==bgc:
                out[rr+dr][cc+dc]=sc; rr+=dr; cc+=dc
    return out

