from collections import Counter

def solve(grid):
    H=len(grid); W=len(grid[0])
    cnt=Counter(v for r in grid for v in r); bg=cnt.most_common(1)[0][0]
    nonbg=[c for c in cnt if c!=bg]
    # dying color = color with fewest cells
    order=sorted(nonbg,key=lambda c:-cnt[c])
    dying_c=order[0]; surv_c=order[-1] if len(order)>1 else None
    # survivor comps
    def comps(cells,grid):
        seen=set(); out=[]
        for p in cells:
            if p in seen: continue
            st=[p]; seen.add(p); cur=[]
            while st:
                a,b=st.pop(); cur.append((a,b))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        q=a+dy,r=b+dx
                        if 0<=q<H and 0<=r<W and (q,r) in cells and (q,r) not in seen:
                            seen.add((q,r)); st.append((q,r))
            out.append(cur)
        return out
    surf=comps([(y,x) for y in range(H) for x in range(W) if grid[y][x]==surv_c],grid)
    # dying cells -> 4 initially
    out=[row[:] for row in grid]
    for y in range(H):
        for x in range(W):
            if grid[y][x]==dying_c: out[y][x]=4
    # each dying cell fires toward nearest survivor cell (manhattan)
    for y in range(H):
        for x in range(W):
            if grid[y][x]!=surv_c and grid[y][x]!=dying_c and grid[y][x]!=bg: pass
            if grid[y][x]==dying_c:
                best=None
                for s in surf:
                    p=s[0][0]; q=s[0][1]
                    d=abs(p-y)+abs(q-x)
                    if best is None or d<best[0]: best=(d,p,q,s)
                d,p,q,s=best
                # direction
                py,y_=y+(p>y); px,q_=x+(q>x)
                py,px=y+(p>y),x+(q>x)
                # walk from dying cell toward survivor, paint bg
                cy,cx=y+(p>y),x+(q>x)
                while 0<=cy<H and 0<=cx<W and grid[cy][cx]==bg:
                    out[cy][cx]=dying_c
                    cy+= (p>y) ; cx+= (q>x)
    return out

